// The forms of the API keys page: the zod schemas that check the inputs.
// Generated by spinup. The application owns this file.
import { z } from 'zod';

/** createSchema checks a new key. Leave the expiry empty for a key that does not expire. */
export const createSchema = z.object({
	name: z
		.string()
		.trim()
		.min(1, 'Enter a name of 1 to 64 characters.')
		.max(64, 'Use 64 characters or fewer.')
		.regex(/^[^\r\n]*$/, 'Use a name without a line break.'),
	scope: z.enum(['read', 'write'], 'Select read or write.'),
	expires_in_days: z
		.number('Use a whole number from 1 to 365.')
		.int('Use a whole number from 1 to 365.')
		.min(1, 'Use a whole number from 1 to 365.')
		.max(365, 'Use a whole number from 1 to 365.')
		.optional()
});

/** revokeSchema checks the revoke of one key. */
export const revokeSchema = z.object({
	id: z.number().int().positive()
});

/** CreateValues holds the values of the create form. */
export type CreateValues = z.infer<typeof createSchema>;
